//! E_028 independently pinned source bytes and hand-calculated metric oracle.
//! PADS source coordinates are MIL; 1 MIL = 25_400 nm.
//! No oracle value is generated by either BoardSI importer.
use boardsi_import::{digest::sha256, e028_cross_format_oracle::{
    qualify_pads_kicad_single_through_via, ViaOracle,
}};
use boardsi_model::ViaKind;

const PADS: &[u8] = include_bytes!("fixtures/e028-via-pads-v94.asc");
const KICAD: &[u8] = include_bytes!("fixtures/e028-via-kicad9.kicad_pcb");

fn hash(hex: &str) -> [u8; 32] {
    assert_eq!(hex.len(), 64);
    let mut out = [0_u8; 32];
    for (index, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[2 * index..2 * index + 2], 16).unwrap();
    }
    out
}

fn oracle() -> ViaOracle {
    ViaOracle {
        copper_layers: 4,
        // Independent design: (300 mil, 200 mil) = (7.620 mm, 5.080 mm).
        centre_nm: [7_620_000, 5_080_000],
        // 35 mil = 0.889 mm; 15 mil = 0.381 mm.
        diameter_nm: 889_000,
        drill_nm: 381_000,
        first_layer: 1,
        last_layer: 4,
        kind: ViaKind::Through,
        pads_sha256: hash("dda44f2b647c8c715c2fe2a3300fed8f0fd34ce7fa683e3ace0e9d4382cc6fba"),
        kicad_sha256: hash("3ea780fea60bb02c91be5dcf91ecc1609cae6c15758b31e6201d8c609bf902f9"),
    }
}
fn txt(bytes: &[u8]) -> String {
    String::from_utf8(bytes.to_vec()).expect("ASCII/UTF8 fixtures")
}
fn check(p: &[u8], k: &[u8], o: &ViaOracle) -> Result<(), &'static str> {
    qualify_pads_kicad_single_through_via(p, k, o).map(|_| ())
}

#[test]
fn e028_exact_three_way_pinned_fixture_and_unknowns() {
    let o = oracle();
    assert_eq!(sha256(PADS), o.pads_sha256, "immutable PADS raw source");
    assert_eq!(sha256(KICAD), o.kicad_sha256, "immutable KiCad raw source");
    let report = qualify_pads_kicad_single_through_via(PADS, KICAD, &o).unwrap();
    assert_eq!(report.pads_sha256, o.pads_sha256);
    assert_eq!(report.kicad_sha256, o.kicad_sha256);
    assert!(report.verified_via_geometry);
    assert!(report.verified_end_pad_geometry_pads_only);
    assert!(!report.kicad_per_layer_pad_contact_verified);
    assert!(!report.electrical_connectivity_verified);
    assert!(!report.solver_ready);
}

#[test]
fn e028_raw_sha_changes_never_silently_pass() {
    let o = oracle();
    let modified_pads = txt(PADS).replace("NET_A", "NET_B");
    let modified_kicad = txt(KICAD).replace("NET_A", "NET_B");
    assert_eq!(check(modified_pads.as_bytes(), KICAD, &o),
        Err("E028_RAW_SOURCE_SHA_MISMATCH"));
    assert_eq!(check(PADS, modified_kicad.as_bytes(), &o),
        Err("E028_RAW_SOURCE_SHA_MISMATCH"));
    // A deliberate repin permits geometry-only equality despite distinct
    // source net names. This test does NOT assert electrical net equivalence.
    let mut repinned = o;
    repinned.pads_sha256 = sha256(modified_pads.as_bytes());
    assert!(check(modified_pads.as_bytes(), KICAD, &repinned).is_ok());
}

#[test]
fn e028_geometry_mutations_fail_even_after_hash_repin() {
    let pairs = [
        // Distinct PADS via coordinate, top pad diameter, drill and inner pad.
        (txt(PADS).replace("300 200 2", "301 200 2"), true),
        (txt(PADS).replace("-2 35 R", "-2 36 R"), true),
        (txt(PADS).replace("V_TEST 15 2", "V_TEST 16 2"), true),
        (txt(PADS).replace("V_TEST 15 2\n-2 35 R\n0 35 R",
                              "V_TEST 15 3\n-2 35 R\n-1 35 R\n0 35 R"), true),
        (txt(KICAD).replace("(at 7.620 5.080)", "(at 7.621 5.080)"), false),
        (txt(KICAD).replace("(size 0.889)", "(size 0.890)"), false),
        (txt(KICAD).replace("(drill 0.381)", "(drill 0.380)"), false),
    ];
    for (changed, is_pads) in pairs {
        let mut repinned = oracle();
        let result = if is_pads {
            assert_ne!(changed.as_bytes(), PADS);
            repinned.pads_sha256 = sha256(changed.as_bytes());
            check(changed.as_bytes(), KICAD, &repinned)
        } else {
            assert_ne!(changed.as_bytes(), KICAD);
            repinned.kicad_sha256 = sha256(changed.as_bytes());
            check(PADS, changed.as_bytes(), &repinned)
        };
        assert!(result.is_err(), "geometry mutation may not PASS: {changed}");
        assert_ne!(result, Err("E028_RAW_SOURCE_SHA_MISMATCH"),
            "test must reach a real geometry/grammar gate");
    }
}

#[test]
fn e028_layer_span_and_unsupported_grammar_fail_closed() {
    let k = txt(KICAD);
    let cases = [
        // Through cannot be silently interpreted as a partial span.
        k.replace("(layers \"F.Cu\" \"B.Cu\")", "(layers \"F.Cu\" \"In1.Cu\")"),
        // Missing physical copper layer must not silently re-index.
        k.replace("(6 \"In2.Cu\" signal)", "(8 \"In3.Cu\" signal)"),
        // Per-layer KiCad copper-pad removal flag cannot become contact proof.
        k.replace("(net 1)\n       (uuid", "(net 1) (remove_unused_layers yes)\n       (uuid"),
        // Unsupported via atom is rejected, not silently dropped.
        k.replace("(via (at", "(via unsupported (at"),
    ];
    for candidate in cases {
        assert_ne!(candidate.as_bytes(), KICAD);
        let mut repinned = oracle();
        repinned.kicad_sha256 = sha256(candidate.as_bytes());
        assert!(check(PADS, candidate.as_bytes(), &repinned).is_err());
    }
    // Source format does not provide independent per-layer KiCad pads,
    // so we must never claim the full-board or electrically connected graph.
    let mut outside = oracle();
    outside.kind = ViaKind::Blind;
    assert_eq!(check(PADS, KICAD, &outside), Err("E028_UNSUPPORTED_ORACLE_SCOPE"));
}

#[test]
fn e028_missing_or_truncated_fixtures_rejected() {
    let mut o = oracle();
    o.pads_sha256 = sha256(&PADS[..PADS.len() - 6]);
    assert!(check(&PADS[..PADS.len() - 6], KICAD, &o).is_err());
    let mut o = oracle();
    o.kicad_sha256 = sha256(&KICAD[..KICAD.len() - 2]);
    assert!(check(PADS, &KICAD[..KICAD.len() - 2], &o).is_err());
}
